INSERT INTO _p VALUES
 ('ENT_STJ_SAGES','PER_ISR_SECOND_TEMPLE','Collective hub for the proto-rabbinic and early Tannaitic sages (Zugot through the redactors of the Mishnah) attested in the Mishnah, Tosefta, and Schäfer''s history; a learned scholarly leadership, not deified.'),
 ('ENT_STJ_DEUTEROCANON','PER_ISR_SECOND_TEMPLE','Collective hub for the human narrative figures of the Apocrypha/deuterocanon (Tobit, Judith, 1-2 Maccabees, additions to Daniel) as attested in the NRSV Apocrypha.'),
 ('ENT_STJ_SIMEON_THE_JUST','PER_ISR_SECOND_TEMPLE','High priest remembered as one of the last of the Great Assembly; opening figure of Pirkei Avot (''the world stands on three things''). Conflated traditions (3rd or 2nd c. BCE) make identity uncertain. Attested in Mishnah Avot and Schäfer.'),
 ('ENT_STJ_HONI','PER_ISR_SECOND_TEMPLE','1st-c. BCE charismatic miracle-working sage who drew a circle and refused to leave until God sent rain (Mishnah Ta''anit 3:8; Josephus, Antiquities 14, as Onias).'),
 ('ENT_STJ_HILLEL','PER_ISR_SECOND_TEMPLE','Foundational Tannaitic sage (late 1st c. BCE-early 1st c. CE), head of the lenient House of Hillel and formulator of the seven middot of interpretation; attested in the Mishnah and Schäfer.'),
 ('ENT_STJ_SHAMMAI','PER_ISR_SECOND_TEMPLE','Contemporary and counterpart of Hillel, head of the stricter House of Shammai; the Hillel-Shammai disputes shape Tannaitic halakhah. Attested in the Mishnah and Schäfer.'),
 ('ENT_STJ_YOHANAN_BEN_ZAKKAI','PER_ISR_SECOND_TEMPLE','Leading 1st-c. CE sage who, per tradition, escaped besieged Jerusalem (70 CE) and founded the academy at Yavneh, reconstituting Judaism after the Temple''s fall. Attested in rabbinic sources and Schäfer.'),
 ('ENT_STJ_AKIVA','PER_ISR_SECOND_TEMPLE','Pre-eminent early-2nd-c. CE Tannaitic sage who systematized halakhah, supported the Bar Kokhba revolt, and was martyred by Rome; foundational to the later Mishnah. Attested in rabbinic literature and Schäfer.'),
 ('ENT_STJ_JUDAH_HANASI','PER_ISR_SECOND_TEMPLE','Patriarch (Nasi) of c. 200 CE traditionally credited with the redaction of the Mishnah, closing the Tannaitic era; attested in rabbinic sources and Schäfer.'),
 ('ENT_STJ_PHILO','PER_ISR_SECOND_TEMPLE','1st-c. CE Hellenistic-Jewish philosopher and exegete of Alexandria who fused Torah with Platonism (the Logos doctrine); historical author of an extensive surviving corpus. Distinct from Philo of Byblos. Attested in his own works and Schäfer.'),
 ('ENT_STJ_JOSEPHUS','PER_ISR_SECOND_TEMPLE','1st-c. CE Jewish historian (Yosef ben Matityahu), Pharisee and former rebel commander, author of The Jewish War and Antiquities of the Jews — the principal narrative source for Second Temple Judaism. Historical figure.'),
 ('ENT_STJ_TEACHER_OF_RIGHTEOUSNESS','PER_ISR_SECOND_TEMPLE','Founding priestly leader and inspired interpreter of the Qumran (Dead Sea Scrolls) community, named in the pesharim and the Damascus Document; historical identity debated. Attested in the Scrolls and Schäfer.'),
 ('ENT_STJ_WICKED_PRIEST','PER_ISR_SECOND_TEMPLE','Sobriquet in the Qumran pesharim for the Jerusalem high priest who persecuted the Teacher of Righteousness; commonly identified with a Hasmonean ruler. Attested in the Dead Sea Scrolls and Schäfer.'),
 ('ENT_STJ_JUDITH','PER_ISR_SECOND_TEMPLE','Pious widow of Bethulia who beheads the Assyrian general Holofernes to save her people; protagonist of the deuterocanonical Book of Judith (NRSV Apocrypha). Literary figure.'),
 ('ENT_STJ_HOLOFERNES','PER_ISR_SECOND_TEMPLE','Assyrian general besieging Bethulia, beheaded by Judith in the Book of Judith (NRSV Apocrypha). Literary antagonist.'),
 ('ENT_STJ_JUDAS_MACCABEUS','PER_ISR_SECOND_TEMPLE','Leader of the Maccabean revolt against the Seleucids who rededicated the Temple (origin of Hanukkah); central figure of 1-2 Maccabees (NRSV Apocrypha) and Josephus. Historical/narrative.'),
 ('ENT_STJ_MACCABEE_BROTHERS','PER_ISR_SECOND_TEMPLE','The five sons of Mattathias (Judas, Jonathan, Simon, John, Eleazar) who led the revolt and founded the Hasmonean line; attested in 1 Maccabees (NRSV Apocrypha).'),
 ('ENT_STJ_MACCABEAN_MOTHER','PER_ISR_SECOND_TEMPLE','Mother who, with her seven sons, is martyred rather than violate the Law under Antiochus IV; named Hannah (Jewish tradition) or Solomonia (Christian tradition). Attested in 2 Maccabees 7 (NRSV Apocrypha).'),
 ('ENT_STJ_ELEAZAR_MARTYR','PER_ISR_SECOND_TEMPLE','Aged scribe martyred under Antiochus IV for refusing to eat swine''s flesh; exemplary martyr of 2 Maccabees 6 (NRSV Apocrypha). Distinct from Eleazar the Maccabee brother.'),
 ('ENT_STJ_ANTIOCHUS_IV','PER_ISR_SECOND_TEMPLE','Seleucid king (r. 175-164 BCE) whose persecution and desecration of the Temple sparked the Maccabean revolt; antagonist of 1-2 Maccabees (NRSV Apocrypha) and Josephus. Distinct from the Carpocratian Epiphanes.'),
 ('ENT_STJ_TOBIAS','PER_ISR_SECOND_TEMPLE','Son of Tobit who journeys with the disguised angel Raphael, marries Sarah, and heals his father''s blindness; protagonist of the Book of Tobit (NRSV Apocrypha).'),
 ('ENT_STJ_SARAH_OF_TOBIT','PER_ISR_SECOND_TEMPLE','Daughter of Raguel, tormented by the demon Asmodeus until freed and married to Tobias through Raphael''s aid (Book of Tobit, NRSV Apocrypha). Homonym distinct from the matriarch Sarah (ENT_ISR_SARAH).'),
 ('ENT_STJ_SUSANNA','PER_ISR_SECOND_TEMPLE','Virtuous wife falsely accused by two elders and vindicated by the young Daniel in the deuterocanonical addition to Daniel (Susanna, NRSV Apocrypha).'),
 ('ENT_STJ_AHIKAR','PER_ISR_SECOND_TEMPLE','Wise Assyrian-court counselor of the Ahikar legend, named as Tobit''s nephew in the Book of Tobit (NRSV Apocrypha); his proverbs circulated widely in the ancient Near East.');
