INSERT INTO _r VALUES
 ('ENT_STJ_SIMEON_THE_JUST','member_of','ENT_STJ_SAGES','high','Simeon the Just opens the chain of transmission in Pirkei Avot, counted among the Sages.'),
 ('ENT_STJ_HONI','member_of','ENT_STJ_SAGES','high','Honi the Circle-Drawer is a charismatic sage attested in the Mishnah and Josephus.'),
 ('ENT_STJ_HILLEL','member_of','ENT_STJ_SAGES','high','Hillel the Elder is a foundational Tannaitic sage.'),
 ('ENT_STJ_SHAMMAI','member_of','ENT_STJ_SAGES','high','Shammai is a foundational Tannaitic sage and counterpart of Hillel.'),
 ('ENT_STJ_YOHANAN_BEN_ZAKKAI','member_of','ENT_STJ_SAGES','high','Yohanan ben Zakkai is a leading post-Temple sage.'),
 ('ENT_STJ_AKIVA','member_of','ENT_STJ_SAGES','high','Akiva ben Joseph is a pre-eminent Tannaitic sage.'),
 ('ENT_STJ_JUDAH_HANASI','member_of','ENT_STJ_SAGES','high','Judah ha-Nasi redacted the Mishnah, closing the Tannaitic chain of sages.'),
 ('ENT_STJ_TEACHER_OF_RIGHTEOUSNESS','member_of','ENT_STJ_SAGES','medium','The Teacher of Righteousness is an inspired sectarian teacher of Second Temple Judaism, grouped with the era''s learned leaders.'),
 ('ENT_STJ_SHAMMAI','opposes','ENT_STJ_HILLEL','high','The House of Shammai (strict) and House of Hillel (lenient) are the paradigmatic Tannaitic halakhic dispute.'),
 ('ENT_STJ_HILLEL','opposed_by','ENT_STJ_SHAMMAI','high','Reciprocal: Hillel''s lenient school is opposed by Shammai''s strict school in the Mishnah.'),
 ('ENT_STJ_AKIVA','taught_by','ENT_STJ_YOHANAN_BEN_ZAKKAI','low','Akiva belongs to the generation of disciples following Yohanan ben Zakkai''s Yavneh academy; lineage attested in rabbinic tradition but indirect.'),
 ('ENT_STJ_JUDAH_HANASI','taught_by','ENT_STJ_AKIVA','medium','Judah ha-Nasi''s Mishnah is built on the halakhic systematization of Akiva (via Akiva''s disciples), the dominant Tannaitic lineage.'),
 ('ENT_NT_GAMALIEL','member_of','ENT_STJ_SAGES','high','Gamaliel the Elder (already in the DB as the Acts figure) is a leading Tannaitic sage, grandson of Hillel; cross-linking the existing entity into the Second Temple sages hub.'),
 ('ENT_NT_GAMALIEL','taught_by','ENT_STJ_HILLEL','medium','Gamaliel the Elder is traditionally Hillel''s grandson and heir of the House of Hillel.'),
 ('ENT_STJ_TEACHER_OF_RIGHTEOUSNESS','opposed_by','ENT_STJ_WICKED_PRIEST','high','The Qumran pesharim depict the Wicked Priest persecuting the Teacher of Righteousness.'),
 ('ENT_STJ_WICKED_PRIEST','opposes','ENT_STJ_TEACHER_OF_RIGHTEOUSNESS','high','Reciprocal: the Wicked Priest is the persecutor of the Teacher of Righteousness in the Dead Sea Scrolls.'),
 ('ENT_STJ_JOSEPHUS','member_of','ENT_STJ_SAGES','medium','Josephus identifies as a Pharisee and learned interpreter of the Law; grouped with the era''s learned figures (historian).'),
 ('ENT_STJ_JUDITH','member_of','ENT_STJ_DEUTEROCANON','high','Judith is the protagonist of the deuterocanonical Book of Judith.'),
 ('ENT_STJ_HOLOFERNES','member_of','ENT_STJ_DEUTEROCANON','high','Holofernes is the antagonist of the Book of Judith.'),
 ('ENT_STJ_JUDITH','opposes','ENT_STJ_HOLOFERNES','high','Judith beheads the Assyrian general Holofernes to save Bethulia.'),
 ('ENT_STJ_HOLOFERNES','opposed_by','ENT_STJ_JUDITH','high','Reciprocal: Holofernes is slain by Judith.'),
 ('ENT_STJ_JUDAS_MACCABEUS','member_of','ENT_STJ_DEUTEROCANON','high','Judas Maccabeus is the central figure of 1-2 Maccabees.'),
 ('ENT_STJ_JUDAS_MACCABEUS','member_of','ENT_STJ_MACCABEE_BROTHERS','high','Judas is one of the five Maccabee brothers, sons of Mattathias.'),
 ('ENT_STJ_MACCABEE_BROTHERS','member_of','ENT_STJ_DEUTEROCANON','high','The Maccabee brothers are deuterocanonical narrative figures of 1 Maccabees.'),
 ('ENT_STJ_MACCABEE_BROTHERS','opposes','ENT_STJ_ANTIOCHUS_IV','high','The Maccabee brothers lead the revolt against the persecuting Seleucid king Antiochus IV.'),
 ('ENT_STJ_ANTIOCHUS_IV','member_of','ENT_STJ_DEUTEROCANON','high','Antiochus IV Epiphanes is the chief antagonist of 1-2 Maccabees.'),
 ('ENT_STJ_ANTIOCHUS_IV','opposed_by','ENT_STJ_JUDAS_MACCABEUS','high','Antiochus IV is opposed by Judas Maccabeus, who rededicates the desecrated Temple.'),
 ('ENT_STJ_MACCABEAN_MOTHER','member_of','ENT_STJ_DEUTEROCANON','high','The Maccabean mother is a martyr figure of 2 Maccabees 7.'),
 ('ENT_STJ_MACCABEAN_MOTHER','opposed_by','ENT_STJ_ANTIOCHUS_IV','high','The mother and her seven sons are martyred under Antiochus IV in 2 Maccabees 7.'),
 ('ENT_STJ_ELEAZAR_MARTYR','member_of','ENT_STJ_DEUTEROCANON','high','Eleazar the scribe is the exemplary martyr of 2 Maccabees 6.'),
 ('ENT_STJ_ELEAZAR_MARTYR','opposed_by','ENT_STJ_ANTIOCHUS_IV','high','Eleazar is martyred under the persecution of Antiochus IV.'),
 ('ENT_STJ_TOBIAS','member_of','ENT_STJ_DEUTEROCANON','high','Tobias is the protagonist of the Book of Tobit.'),
 ('ENT_STJ_TOBIAS','child_of','ENT_TOBIT','high','Tobias is the son of Tobit (existing entity ENT_TOBIT) in the Book of Tobit.'),
 ('ENT_TOBIT','parent_of','ENT_STJ_TOBIAS','high','Reciprocal: Tobit is the father of Tobias; wiring the existing ENT_TOBIT into the cohort.'),
 ('ENT_STJ_SARAH_OF_TOBIT','member_of','ENT_STJ_DEUTEROCANON','high','Sarah of Tobit is a narrative figure of the Book of Tobit.'),
 ('ENT_STJ_SARAH_OF_TOBIT','spouse_of','ENT_STJ_TOBIAS','high','Sarah marries Tobias after being freed from the demon Asmodeus.'),
 ('ENT_STJ_TOBIAS','spouse_of','ENT_STJ_SARAH_OF_TOBIT','high','Reciprocal: Tobias marries Sarah in the Book of Tobit.'),
 ('ENT_STJ_TOBIAS','guided_by','ENT_ISR_RAPHAEL','high','Tobias is guided on his journey by the disguised archangel Raphael (existing ENT_ISR_RAPHAEL) in the Book of Tobit.'),
 ('ENT_STJ_SARAH_OF_TOBIT','rescued_by','ENT_ISR_RAPHAEL','high','Raphael binds the demon Asmodeus and frees Sarah, enabling her marriage (Book of Tobit).'),
 ('ENT_STJ_AHIKAR','member_of','ENT_STJ_DEUTEROCANON','medium','Ahikar appears as Tobit''s nephew within the Book of Tobit''s deuterocanonical narrative.'),
 ('ENT_STJ_SUSANNA','member_of','ENT_STJ_DEUTEROCANON','high','Susanna is the heroine of the deuterocanonical addition to Daniel.');
INSERT INTO entity_relationships(subject_entity_id,relationship_type,object_entity_id,confidence,rationale,source_id,review_status)
